import { Image } from "expo-image";
import type { ImageStyle, StyleProp } from "react-native";

/** Intrinsic size of `assets/images/nesafric-logo.png` (generated by `scripts/generate-brand-assets.mjs`). */
export const LOGO_ASPECT = 1200 / 333;

/**
 * The official NesAfric logo, one asset for every screen that shows it. Pass a height; the width
 * follows the logo's own proportions so it is never stretched or clipped.
 */
export function BrandLogo({ height, style, testID = "brand-logo" }: { height: number; style?: StyleProp<ImageStyle>; testID?: string }) {
  return (
    <Image
      source={require("../../assets/images/nesafric-logo.png")}
      style={[{ height, width: Math.round(height * LOGO_ASPECT) }, style]}
      contentFit="contain"
      accessibilityLabel="NesAfric"
      accessibilityRole="image"
      testID={testID}
    />
  );
}
